def find_connected_components(grid, target_color):
    height, width = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] == target_color and (r, c) not in visited:
                cells = []
                queue = [(r, c)]
                visited.add((r, c))

                while queue:
                    cr, cc = queue.pop(0)
                    cells.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == target_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                if len(cells) >= 5:
