def try_simple_5_fill(grid):
    """For each row, fill between consecutive 5s with 2s"""
    result = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])

    for r in range(height):
        # Find indices of 5s in this row
        five_locs = [c for c in range(width) if result[r][c] == 5]

        if len(five_locs) < 2:
            continue

        # Fill between consecutive 5s
        for i in range(len(five_locs) - 1):
            c1, c2 = five_locs[i], five_locs[i+1]
            # Fill cols between c1 and c2 (exclusive) if they are 0
            for c in range(c1 + 1, c2):
                if result[r][c] == 0:
                    result[r][c] = 2

    return result

