def find_frames(grid, colors_to_detect, height, width, visited=None):
    """
    Find all rectangular frames of specified colors and return fill info
    A frame is defined by:
    - All border cells are the same color (from colors_to_detect)
    - At least 5 cells total, with interior of at least 1x1
    """
    frame_fills = {}

    if visited is None:
        visited = set()

    processed = set()

    for cr in range(height):
        for cc in range(width):
            if grid[cr][cc] not in colors_to_detect or (cr, cc) in processed:
                continue

            color = grid[cr][cc]
            cells = []
            queue = deque([(cr, cc)])
            local_visited = set()

            while queue:
                current_c, current_r = queue.popleft()
                cells.append((current_c, current_r))
                local_visited.add((current_c, current_r))

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = current_r + dr, current_c + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if (nr, nc) not in local_visited and grid[nr][nc] == color:
                            local_visited.add((nr, nc))
                            queue.append((nr, nc))

            if len(cells) < 5:
                processed.update(cells)
                continue

            rows = sorted(set(r for r, c in cells))
            cols = sorted(set(c for r, c in cells))
            top, bottom = rows[0], rows[-1]
            left, right = cols[0], cols[-1]

            # Check if all border cells are of this color
            is_frame = True
            for rf in [top, bottom]:
                for cf in range(left, right + 1):
                    if (rf, cf) not in cells:
                        is_frame = False
                        break
                if not is_frame:
                    break

            if not is_frame:
                processed.update(cells)
                continue

            for cf in [left, right]:
                for rf in range(top + 1, bottom):
                    if (rf, cf) not in cells:
                        is_frame = False
                        break
                if not is_frame:
                    break

            if not is_frame:
                processed.update(cells)
                continue

            # Valid frame - calculate interior size
            interior_height = bottom - top - 1
            interior_width = right - left - 1
            interior_cells_count = interior_height * interior_width

            # Mark for filling (we'll apply fills separately)
            frame_fills[color] = (top, bottom, left, right, interior_height, interior_width)
            processed.update(cells)

    return frame_fills, processed

def compute_fill_value(interior_height, interior_width):
    """7 for odd-square interior, 2 otherwise"""
    return 7 if (interior_height == interior_width) and (interior_height % 2 == 1) else 2

def find_color_boundaries(grid, color, height, width):
    """Get all cells of a specified color"""
    cells = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == color]
    if not cells:
        return []

    rows = sorted(set(r for r, c in cells))
    cols = sorted(set(c for r, c in cells))

    return {
        'color': color,
        'min_row': rows[0], 'max_row': rows[-1],
        'min_col': cols[0], 'max_col': cols[-1],
        'total_cells': len(cells)
    }

def apply_frame_fills(grid, frame_fills, height, width):
    """Apply fills to frame interiors"""
    result = [row[:] for row in grid]

    for color, (top, bottom, left, right, inner_h, inner_w) in frame_fills.items():
        fill_val = compute_fill_value(inner_h, inner_w)
        print(f"Frame: color={color}, bbox=[{top},{bottom}]x[{left},{right}], interior={inner_h}x{inner_w}, fill={fill_val}")

        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if result[r][c] == 0:
                    result[r][c] = fill_val

    return result

