                corner_colors = set()
                for tr, tc in corners:
                    if 0 <= tr < height and 0 <= tc < width:
                        corner_colors.add(result[tr][tc])

                # This is getting complex, let me use a simpler approach
                # Check if component is "enclosed" by same-color frame
                # by checking the perimeter of the bbox
                perimeter_ok = True
                for pf in [top, bottom]:
                    for pc in range(left, right + 1):
                        if (pf, pc) not in comp_cells:
                            perimeter_ok = False
