                    for pc in range(max(0, left - 1), min(width, right + 2)):
                        for pr in range(max(0, top - 1), min(height, bottom + 2)):
                            if (pr, pc) not in comp_cells and grid[pr][pc] != background:
                                if found_frame_color is None:
                                    found_frame_color = grid[pr][pc]
                    if found_frame_color:
                        frame_fills[found_frame_color] = (top, bottom, left, right)
                    processed_bg.update(comp_cells)
                    continue

                processed_bg.update(comp_cells)

    # Now detect frames differently: for each color, look for rectangular patterns
    for color in [1, 5, 6]:
        cells = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == color]

        # Find connected components and check each for frame-ness
        visited = set()
        for r, c in cells:
            if (r, c) in visited:
                continue

            comp = []
            queue = deque([(r, c)])
            local_visited = {(r, c)}
            while queue:
                pr, pc = queue.popleft()
                comp.append((pr, pc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = pr + dr, pc + dc
                    if (0 <= nr < height and 0 <= nc < width and (nr, nc) not in local_visited):
                        if grid[nr][nc] == color:
                            local_visited.add((nr, nc))
