            # Check frame-ness
            rows = sorted(set(p[0] for p in comp))
            cols = sorted(set(p[1] for p in comp))
            top, bottom = rows[0], rows[-1]
            left, right = cols[0], cols[-1]

            is_frame = True
            for pf in [top, bottom]:
                for pc in range(left, right + 1):
