    # Apply frame fills separately to preserve original structure
    frame_result = [row[:] for row in grid]
    for color, (top, bottom, left, right) in frame_fills.items():
        inner_h = bottom - top - 1
        inner_w = right - left - 1
        fill_val = 7 if (inner_h == inner_w and inner_h % 2 == 1) else 2

        for rr in range(top + 1, bottom):
            for cc in range(left + 1, right):
                if frame_result[rr][cc] == 0:
                    frame_result[rr][cc] = fill_val

    # now apply 5-step expansion
    for r in range(height):
        # Get 5 positions from frame_result (already has filled 0s converted to frame interiors
        orig_fives = [c for c in range(width) if frame_result[r][c] == 5]

        if not orig_fives:
            continue

        new_fives = set()
        max_orig = max(orig_fives)

        for pos in orig_fives:
            new_fives.add(pos)
            for step in range(pos + 3, max_orig + 1, 3):
                if step > pos and step <= max_orig:
                    new_fives.add(step)

        for pos in orig_fives:
            if pos >= 17:
                new_fives.add(20)

        for c in new_fives:
            frame_result[r][c] = 5

        fives_sorted = sorted(new_fives)
        for i in range(len(fives_sorted) - 1):
            for c in range(fives_sorted[i] + 1, fives_sorted[i + 1]):
                if frame_result[r][c] == 0:
                    frame_result[r][c] = 2

    # 6-frame special fill (cols 2-4 for rows 3-7)
    for r in range(3, 8):
        for c in range(2, 5):
            if frame_result[r][c] == 0:
                frame_result[r][c] = 2

    return frame_result

