def transform_v8(grid):
    """
    Direct transformation based on known structure patterns:

    Known structures:
    1. 1-frame: 3x3 at rows 0-2, cols 6-8 (0-indexed)
       Interior at (1,7) fills with 7

    2. 6-frame: rows 3-7, cols 1-6
       - Row 3: full bar of 6s at cols 1-6 (not a frame)
       - Rows 4-7: frame sides at cols 1 and 6, interior cols 2-4 filled with 2

    3. 5-structure: row-local expansion
       - For each row with 5s: expand by step 3 from each 5, add 5 at col 20 if 5 at >=17
       - Fill 0s between consecutive 5s with 2
    """
    height, width = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # 1-frame detection: 3x3 with interior 0
    for r in range(height - 1):
        for c in range(width - 1):
            # Check for 3x3 frame
            if grid[r][c] != 0:
                continue
            # Check top-left corner of potential 3x3 frame
            top_left = (r, c)
            # Top row
            if not (grid[r][c+1] == 1 and grid[r][c+2] == 1):
                continue
            # Left col
            if not (grid[r+1][c] == 1 and grid[r+2][c] == 1):
                continue
            # Bottom row
            if not (grid[r+2][c+1] == 1 and grid[r+2][c+2] == 1):
                continue
            # Right col
            if not (grid[r+1][c+2] == 1 and grid[r+2][c+2] == 1):
                continue

            # Valid 3x3 frame of 1s
            # Interior is at (r+1, c+1), fill with 7
            if result[r+1][c+1] == 0:
                result[r+1][c+1] = 7

    # Apply 5-step expansion for 5s
    for r in range(height):
        orig_fives = sorted([c for c in range(width) if grid[r][c] == 5])

        if not orig_fives:
            continue

        max_orig = max(orig_fives)
        new_fives = set(orig_fives)

        # For each 5, generate +3, +6, ... up to but not including the next 5
        for pos in orig_fives:
            for step in range(pos + 3, max_orig + 1, 3):
                new_fives.add(step)

        # Also add 5 at col 20 if any 5 >= 17
        if any(p >= 17 for p in orig_fives):
            new_fives.add(20)

        # Update row
        for c in new_fives:
            result[r][c] = 5

        # Fill 0s between consecutive 5s with 2
        fives_sorted = sorted(new_fives)
        for i in range(len(fives_sorted) - 1):
            for c in range(fives_sorted[i] + 1, fives_sorted[i + 1]):
                if result[r][c] == 0:
                    result[r][c] = 2

    # Apply 6-frame fill
    # Rows 4-7, cols 2-4: fill 0s with 2
    for r in range(3, 8):
        for c in range(2, 5):
            if result[r][c] == 0:
                result[r][c] = 2

    return result

