                top -= 1

            while down < height - 1 and grid[down+1][c] == color:
                down += 1

            if left >= right or top >= down:
                continue

            # Check all borders are solid
            is_valid = True

            for cf in range(left, right + 1):
                if grid[top][cf] != color or grid[down][cf] != color:
                    is_valid = False
                    break

            if not is_valid:
                for rf in range(top, down + 1):
                    if grid[rf][left] != color or grid[rf][right] != color:
                        is_valid = False
                        break

            if not is_valid:
                continue

            # Unique bbox key
            key = (top, bottom, left, right) = (top, down, left, right)
            if key in seen:
                continue
            seen.add(key)

            inner_h = down - top - 1
            inner_w = right - left - 1
            fill_val = 7 if (inner_h == inner_w) and (inner_h % 2 == 1) else 2

            frames.append({
                'r1': top, 'r2': down,
                'c1': left, 'c2': right,
                'inner_h': inner_h, 'inner_w': inner_w,
                'fill_val': fill_val
            })

    return frames

def transform_v11(grid):
    height, width = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    frames = detect_unique_rectangles(grid, height, width)
    print(f"Detected {len(frames)} unique frames:")
    for fr in frames:
        print(f"  color boundary at [{fr['r1']},{fr['r2']}]x[{fr['c1']},{fr['c2']}], inner={fr['inner_h']}x{fr['inner_w']}, fill={fr['fill_val']}")

    for fr in frames:
        for r in range(fr['r1'] + 1, fr['r2']):
            for c in range(fr['c1'] + 1, fr['c2']):
                if result[r][c] == 0:
                    result[r][c] = fr['fill_val']

    return result

